/** Independent Boolean incidence/yen model;imports no producer or renderer. */
import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import fixed from'./legacy-2019-pm-integration-matrices.json';import{legacy2019PmIntegrationReview as review}from'./legacy-2019-pm-integration-review';
export const legacy2019PmIntegrationInputs=()=>Array.from({length:27},(_,i)=>[Math.floor(i/3),i%3]);
export function legacy2019PmIntegrationModel(values:number[]){
 assert.equal(values.length,2);assert(Number.isInteger(values[0])&&values[0]>=0&&values[0]<=8);assert(Number.isInteger(values[1])&&values[1]>=0&&values[1]<=2);
 const bits=fixed.matrices[values[0]],factors=[5,4,6],pools=[[500],[200,200],[300],[50,150,100]],at=[0,0,0,0],cells=bits.map(n=>pools.map((pool,d)=>n&(1<<d)?pool[at[d]++]*factors[values[1]]/5:null)),totals=pools.map(pool=>pool.reduce((a,b)=>a+b,0)*factors[values[1]]/5);
 const incidence=Array.from({length:4},()=>Array(6).fill(false)),design=[0,1,2,0],forecast=[3,4,4,5],proc=[0,1,2,3,2,2];cells.forEach((row,f)=>row.forEach((v,d)=>{if(v!==null){incidence[proc[f]][design[d]]=true;incidence[proc[f]][forecast[d]]=true;}}));
 const leaves='ABCEFG',destinations=Array.from({length:6},(_,j)=>'VWXY'.split('').filter((_,i)=>incidence[i][j])),neighbors=incidence.map(row=>leaves.split('').filter((_,j)=>row[j])),degrees=destinations.slice(0,3).map(r=>r.length),a=degrees.map((n,i)=>n===Math.max(...degrees)?i:-1).filter(n=>n>=0);assert.equal(a.length,1);const b=degrees[a[0]],peak=Math.max(...neighbors.map(n=>n.length)),cd=neighbors.flatMap((n,i)=>n.length===peak?[i]:[]);assert.equal(cd.length,2);const g=[3,4].filter(i=>destinations[5].every(p=>destinations[i].includes(p))).map(i=>leaves[i]),gIndex=g.length===2?2:g[0]==='E'?0:g[0]==='F'?1:3,links=incidence.flat().filter(Boolean).length,total=totals.reduce((a,b)=>a+b,0),yen=100_000_000;
 const beforeYen=19*yen+total*yen/1000+links*yen/10,afterYen=6*yen+total*yen/1000+2*yen/10;assert(Number.isSafeInteger(beforeYen)&&Number.isSafeInteger(afterYen));const format=(n:number)=>{assert(Number.isInteger(n));return`${Math.floor(n/10)}.${n%10}`;},before=beforeYen/(yen/10),after=afterYen/(yen/10),e=[190,190+links,before,240+links],f=[60,62,after,after+20];
 return{cells,totals,total,incidence,destinations,neighbors,a:a[0],b,cd,gIndex,links,peak,e:e.map(format),f:f.map(format),before,after,format};
}
const choiceText=(b:GeneratedBody['prompt'])=>{assert.equal(b.length,1);assert(b[0].type==='paragraph');return b[0].text;};
