 const prompt=body.prompt.filter(b=>b.type==='paragraph').map(b=>b.text).join('\n');for(const s of['設問1〜3','一つ以上の事業部の製品を製造','2018年度','設計システムには三つ、需要予測システムには三つ、調達システムには四つ','システムの名称が同一の場合','同じシステムを共用','P事業部とS事業部','データの受渡し','部品の在庫管理と発注処理','その工場が製造する製品を担当している事業部','設計システムと需要予測システムとの間のデータ連携はない','設計システム数と需要予測システム数の合計が最も多い','年間2億円','年間3億円','年間1億円','年間の取扱高の0.1%','データ連携経路一つ当たり年間0.1億円','今までデータ連携していないシステム間に新たな','全社でそれぞれ一つに統合','取扱高などの前提条件は変わらない','単独で利用する場合と変わらない','保守サポート期間の終了','新たなデータ連携経路を作成することなくGシステムの代替'])assert(prompt.includes(s),'Missing premise '+s);
 const tables=body.prompt.filter(b=>b.type==='table');assert.equal(tables.length,2);assert.deepEqual(tables[0].columns,['事業部','設計システム','需要予測システム']);assert.deepEqual(tables[0].rows,[['P事業部','Aシステム','Eシステム'],['Q事業部','Bシステム','Fシステム'],['R事業部','Cシステム','Fシステム'],['S事業部','Aシステム','Gシステム']]);assert.deepEqual(tables[1].columns,['製造工場','調達システム']);assert.deepEqual(tables[1].rows,'HIJKLM'.split('').map((f,i)=>[f+'製造工場',['V','W','X','Y','X','X'][i]+'システム']));
 const figures=body.prompt.filter(b=>b.type==='diagram');assert.equal(figures.length,1);const t=figures[0];assert(t.scene.kind==='source_figure');assert.equal(t.scene.profile,'legacy-2019-manufacturing-turnover');assert.deepEqual(t.scene.values,values);assert.equal(t.caption,'表1 2018年度に各製造工場が製造した製品の事業部別取扱高');for(const s of['単位は億円','製造工場と事業部','P、Q、R、S','−は当該工場が当該事業部の製品を製造していない'])assert(t.alt.includes(s));m.cells.forEach((row,i)=>assert(t.alt.includes('HIJKLM'[i]+'製造工場：'+row.map((v,j)=>'PQRS'[j]+'事業部'+(v===null?'−':v)).join('、'))));assert(t.alt.includes('合計：'+m.totals.map((v,i)=>'PQRS'[i]+'事業部'+v).join('、')));
 for(const s of['同名のシステムは共用','同じ相手への経路は一つ','設計と需要予測の間へ経路を足したりしない',`aは${'ABC'[m.a]}、bは${m.b}`,`最多は${m.peak}で、c/dは${m.cd.map(i=>'VWXY'[i]).join('と')}を順不同で選ぶ`,`年間取扱高は${m.totals.join('+')}=${m.total}`,`0.1%は${m.format(m.total/100)}億円`,`一意な連携経路は${m.links}本`,`19.0+${m.format(m.total/100)}+${m.format(m.links)}=${m.format(m.before)}`,`24.0+${m.format(m.links)}=${m.format(240+m.links)}`,'共用と費用範囲の両方が異なる',`6.0+${m.format(m.total/100)}+0.2=${m.format(m.after)}`,`${m.format(m.after+20)}は統合後も設計システムを余分に一つ`,`Gの接続先は${m.destinations[5].join('/')}、Eは${m.destinations[3].join('/')}、Fは${m.destinations[4].join('/')}`,'Gの接続先を全て既存の接続先として持つ','一部の相手との接続だけや、包含関係を逆にした判定では足りない',`gは「${review.originalG[m.gIndex]}」`])assert(body.explanation.includes(s),'Missing reviewed reasoning '+s);'ABC'.split('').forEach((n,i)=>assert(body.explanation.includes(n+'：'+m.destinations[i].join('/')+'（'+m.destinations[i].length+'システム）')));'VWXY'.split('').forEach((n,i)=>assert(body.explanation.includes(n+'：'+m.neighbors[i].join('/')+'（'+m.neighbors[i].length+'システム）')));
 for(const numbers of[m.e,m.f]){assert.equal(new Set(numbers).size,4);numbers.forEach(n=>assert(/^\d+\.\d$/.test(n)));assert(numbers.filter(n=>n===numbers[2]).length===1);assert(Math.min(...numbers.filter((_,i)=>i!==2).map(n=>Math.abs(Number(n)-Number(numbers[2]))))>=1.2-1e-8);}assert(!/選択肢[アイウエ]|公式の誤答|公式意図|生成条件|転載/.test(body.explanation));
 return{memberships:28,pairChecks:16,answers:{a:m.a,b:m.b,cd:m.cd,e:m.e[2],f:m.f[2],g:m.gIndex}};
